Status validate_naval_capture_history(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& mc,const NavalAssetState& a,const NavalCatalog& n,const NavalBattleState& b,const NavalCaptureFact& f,const NavalNavigationState* navigation,const NavalOriginalSourceContext* original){return naval_repair_exact_detail::status([&]{if(original)naval_repair_exact_detail::take(decision_source_boundary(c,m,mc,*original,f.id,"naval_capture"));naval_repair_exact_detail::take(capture_history_impl(c,m,mc,a,n,b,f,navigation,original));});}
